/** Popover (dropdown) panel: small fade + slide from the trigger. */
export function popoverMotion(reduced: boolean) {
    if (reduced) {
        return {
            initial: { opacity: 0 },
            animate: { opacity: 1 },
            exit: { opacity: 0 },
            transition: { duration: DURATION.fast },
        };
